insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-st-241","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A one-molar aqueous solution is prepared so that one litre of the finished solution contains","options":["1 mol of solute","1 mol of solvent only","1 g of solute","1 kg of solute"],"answer_index":0,"explanation":"Molarity is moles of solute per litre of solution; 1 M means 1 mol in 1 L of solution.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molarity-dilution"},{"id":"che-st-242","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Half a mole of glucose is dissolved and the solution is made up to 250 mL. The molarity of that solution is","options":["0.50 M","1.0 M","2.0 M","4.0 M"],"answer_index":2,"explanation":"$M = 0.50 / 0.250 = 2.0$ mol L$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molarity-dilution"},{"id":"che-st-243","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"When a solution is diluted with solvent, the product $M_1V_1$ compared with $M_2V_2$ is","options":["larger after dilution","smaller after dilution","unchanged, because solute moles stay the same","equal to the density"],"answer_index":2,"explanation":"Dilution conserves the amount of solute, so $M_1V_1 = M_2V_2$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molarity-dilution"},{"id":"che-st-244","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Two moles of NaOH pellets are dissolved and the solution is made up to 1.00 L. The molarity of the alkali is","options":["0.50 M","1.0 M","2.0 M","4.0 M"],"answer_index":2,"explanation":"$M = 2.0\\ \\mathrm{mol} / 1.00\\ \\mathrm{L} = 2.0$ M.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molarity-dilution"},{"id":"che-st-245","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Four grams of NaOH (M = 40 g mol$^{-1}$) are dissolved and made up to 500 mL. The molarity of the solution is","options":["0.10 M","0.20 M","0.40 M","2.0 M"],"answer_index":1,"explanation":"Moles of NaOH $= 4/40 = 0.10$; $M = 0.10 / 0.50 = 0.20$ M.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molarity-dilution"},{"id":"che-st-246","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A 100 mL portion of 2.0 M HCl is diluted with water to 500 mL. The molarity after dilution is","options":["0.20 M","0.40 M","1.0 M","2.0 M"],"answer_index":1,"explanation":"$M_2 = (2.0 \\times 100)/500 = 0.40$ M.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"molarity-dilution"},{"id":"che-st-247","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A student must prepare 250 mL of 1.0 M $\\mathrm{H_2SO_4}$ from a 5.0 M stock. The volume of stock that should be pipetted is","options":["25 mL","50 mL","100 mL","200 mL"],"answer_index":1,"explanation":"$V_1 = (1.0 \\times 250)/5.0 = 50$ mL of stock, then diluted to 250 mL.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"molarity-dilution"},{"id":"che-st-248","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"200 mL of 0.50 M NaCl is mixed with 300 mL of 1.50 M NaCl (volumes additive). The molarity of the blended solution is","options":["0.90 M","1.00 M","1.10 M","1.20 M"],"answer_index":2,"explanation":"Solute moles $= 0.10 + 0.45 = 0.55$; total volume $= 0.50$ L, so $M = 1.10$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"molarity-dilution"},{"id":"che-ek-101","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Electrical conductance of a solution is defined as the","options":["reciprocal of its resistance","product of resistance and cell constant","same quantity as resistivity","reciprocal of molar conductivity"],"answer_index":0,"explanation":"Conductance $G = 1/R$. A smaller resistance means the solution conducts more readily.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance"},{"id":"che-ek-102","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The SI unit used for electrical conductance is the","options":["siemens (S)","ohm ($\\Omega$)","farad (F)","tesla (T)"],"answer_index":0,"explanation":"Siemens is the reciprocal ohm. Older texts also write mho for the same unit.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance"},{"id":"che-ek-103","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Specific conductivity $\\kappa$ of an electrolyte solution is the conductance of","options":["a unit cube of the solution between opposite faces","one mole of solute placed between inert plates","the salt bridge alone","a metallic wire of the same length"],"answer_index":0,"explanation":"$\\kappa$ is intensive: it is $G$ measured for unit length and unit cross-section of solution.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance"},{"id":"che-ek-104","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The cell constant of a conductivity cell equals","options":["distance between electrodes divided by electrode area","electrode area divided by distance between electrodes","resistance multiplied by current","molar conductivity divided by $\\kappa$"],"answer_index":0,"explanation":"Cell constant $= \\ell/A$. It converts the measured conductance into specific conductivity.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance"},{"id":"che-ek-105","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Specific conductivity is obtained from the measured conductance $G$ by writing","options":["$\\kappa = G \\times (\\ell/A)$","$\\kappa = G \\times A/\\ell$","$\\kappa = G^2 \\times \\ell/A$","$\\kappa = (\\ell/A)/G$"],"answer_index":0,"explanation":"Because $G = \\kappa A/\\ell$, rearranging gives $\\kappa = G \\times$ cell constant.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance"},{"id":"che-ek-106","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Molar conductivity $\\Lambda_m$ is related to specific conductivity and molar concentration $c$ by","options":["$\\Lambda_m = \\kappa/c$","$\\Lambda_m = \\kappa \\times c$","$\\Lambda_m = c/\\kappa$","$\\Lambda_m = \\kappa + c$"],"answer_index":0,"explanation":"In SI, $\\Lambda_m = \\kappa/c$. In older cgs usage one writes $\\Lambda_m = 1000\\,\\kappa/M$ with $M$ in mol L$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance"},{"id":"che-ek-107","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"As an aqueous electrolyte is made more dilute, its specific conductivity $\\kappa$ generally","options":["falls because fewer ions occupy each cubic centimetre","rises because every ion becomes heavier","stays fixed at the value of pure water","becomes equal to $\\Lambda_m^\\circ$"],"answer_index":0,"explanation":"Dilution lowers the number of charge carriers per unit volume, so $\\kappa$ decreases even though ions may move more freely.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance"},{"id":"che-ek-108","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The usual laboratory unit of cell constant is","options":["cm$^{-1}$","S cm$^2$ mol$^{-1}$","ohm","mol L$^{-1}$"],"answer_index":0,"explanation":"$\\ell/A$ has dimensions of inverse length, so cm$^{-1}$ or m$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance"},{"id":"che-ek-109","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For a strong electrolyte such as KCl, further dilution produces","options":["only a modest further rise in $\\Lambda_m$","a sudden drop of $\\Lambda_m$ to zero","no change at all in $\\Lambda_m$","a collapse of $\\kappa$ to a negative value"],"answer_index":0,"explanation":"Strong electrolytes are already fully ionised; $\\Lambda_m$ creeps up mainly because interionic drag weakens.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance"},{"id":"che-ek-110","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Metallic conduction differs from electrolytic conduction in that metals carry current by","options":["mobile electrons, without chemical change of the conductor","migration of cations and anions that are discharged at electrodes","protons hopping through a salt bridge only","neutral solvent molecules drifting in the field"],"answer_index":0,"explanation":"A metal conducts via its electron gas. An electrolyte conducts by ion movement and is chemically changed at the electrodes.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance"},{"id":"che-ek-111","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A conductivity cell of constant $1.5\\ \\mathrm{cm^{-1}}$ reads $G = 0.020\\ \\mathrm{S}$ for a solution. The specific conductivity is","options":["$0.030\\ \\mathrm{S\\ cm^{-1}}$","$0.013\\ \\mathrm{S\\ cm^{-1}}$","$0.075\\ \\mathrm{S\\ cm^{-1}}$","$1.5\\ \\mathrm{S\\ cm^{-1}}$"],"answer_index":0,"explanation":"$\\kappa = G \\times (\\ell/A) = 0.020 \\times 1.5 = 0.030\\ \\mathrm{S\\ cm^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"conductance"},{"id":"che-ek-112","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"If $\\kappa = 0.0050\\ \\mathrm{S\\ cm^{-1}}$ for a $0.020\\ \\mathrm{M}$ solution, $\\Lambda_m$ in S cm$^2$ mol$^{-1}$ equals","options":["250","0.25","4.0","100"],"answer_index":0,"explanation":"$\\Lambda_m = 1000\\,\\kappa/c = 1000 \\times 0.0050 / 0.020 = 250\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"conductance"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
insert into question_pyq_meta (question_id, appear_count, years, exams, verified) select question_id, appear_count, years, exams, verified from jsonb_to_recordset($meta$[{"question_id":"che-st-241","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-242","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-243","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-244","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-245","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-246","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-247","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-248","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-101","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-102","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-103","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-104","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-105","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-106","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-107","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-108","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-109","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-110","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-111","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-112","appear_count":0,"years":[],"exams":[],"verified":false}]$meta$::jsonb) as t(question_id text, appear_count int, years int[], exams text[], verified boolean) on conflict (question_id) do update set appear_count = excluded.appear_count, years = excluded.years, exams = excluded.exams, verified = excluded.verified;
